<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Trusted Health & Wellness Guidance</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f5faf9;
      --surface: #ffffff;
      --surface-soft: #eef7f5;
      --text: #17363a;
      --muted: #5e7678;
      --primary: #1f8a85;
      --primary-deep: #146a66;
      --accent: #f2a661;
      --coral: #eb7e70;
      --border: #d6e7e4;
      --shadow: 0 10px 30px rgba(19, 65, 70, 0.08);
      --radius: 18px;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #f7fcfb 0%, var(--bg) 100%);
      line-height: 1.5;
    }
    a { color: inherit; text-decoration: none; }
    .container { width: min(1160px, 92vw); margin: 0 auto; }

    .top-ticker {
      background: linear-gradient(90deg, #0f6f6b, #1f8a85);
      color: #effffb;
      border-bottom: 1px solid rgba(255,255,255,0.2);
      overflow: hidden;
      white-space: nowrap;
      position: sticky;
      top: 0;
      z-index: 30;
    }
    .ticker-track {
      display: inline-block;
      padding: 12px 0;
      animation: ticker 26s linear infinite;
      font-weight: 600;
      letter-spacing: .2px;
    }
    .ticker-item { margin: 0 28px; display: inline-flex; align-items: center; gap: 10px; }
    .ticker-dot { width: 8px; height: 8px; border-radius: 999px; background: var(--accent); }
    @keyframes ticker {
      from { transform: translateX(0); }
      to { transform: translateX(-50%); }
    }

    header { background: rgba(255,255,255,0.92); backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); }
    .nav {
      display: flex; align-items: center; justify-content: space-between;
      min-height: 74px;
      position: relative;
    }
    .brand { font-weight: 800; font-size: 1.4rem; color: var(--primary-deep); letter-spacing: .2px; }
    .brand span { color: var(--coral); }
    .menu { display: flex; gap: 14px; }
    .menu button {
      border: 0; background: transparent; color: var(--text); font-weight: 600;
      padding: 10px 12px; border-radius: 10px; cursor: pointer;
    }
    .menu button:hover, .menu button.active { background: var(--surface-soft); color: var(--primary-deep); }
    .mega {
      position: absolute; top: calc(100% + 8px); left: 0; right: 0;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 16px; box-shadow: var(--shadow); padding: 20px;
      display: none; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px;
      z-index: 20;
    }
    .mega.open { display: grid; }
    .mega h4 { margin: 0 0 8px; color: var(--primary-deep); font-size: .95rem; }
    .mega a { display: block; padding: 6px 0; color: var(--muted); font-size: .92rem; }
    .mega a:hover { color: var(--primary); }

    .hero { padding: 34px 0 24px; display: grid; gap: 22px; grid-template-columns: 1.8fr 1fr; }
    .hero-main {
      background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
      box-shadow: var(--shadow); overflow: hidden;
    }
    .hero-main img { width: 100%; height: 300px; object-fit: cover; display: block; }
    .hero-copy { padding: 24px; }
    .eyebrow { color: var(--primary); font-weight: 700; font-size: .82rem; text-transform: uppercase; letter-spacing: .06em; }
    h1 { margin: 8px 0 10px; line-height: 1.2; font-size: clamp(1.7rem, 2.5vw, 2.3rem); }
    .lead { color: var(--muted); max-width: 60ch; }

    .trending {
      background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
      box-shadow: var(--shadow); padding: 18px;
    }
    .trending h3 { margin: 2px 0 14px; }
    .trend-item { padding: 12px 0; border-bottom: 1px solid #e8f0ee; }
    .trend-item:last-child { border-bottom: 0; }
    .tag { color: var(--primary); font-size: .77rem; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; }

    section { padding: 22px 0; }
    .section-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
    h2 { margin: 0; font-size: 1.5rem; }

    .carousel-wrap { position: relative; }
    .carousel {
      display: grid; grid-auto-flow: column; grid-auto-columns: minmax(160px, 1fr);
      gap: 16px; overflow-x: auto; scroll-behavior: smooth; padding-bottom: 8px;
      scrollbar-width: none;
    }
    .carousel::-webkit-scrollbar { display: none; }
    .topic {
      background: var(--surface); border: 1px solid var(--border); border-radius: 999px;
      padding: 12px 12px 12px 12px; display: flex; align-items: center; gap: 12px;
      box-shadow: 0 6px 20px rgba(17,62,66,0.06);
    }
    .topic img { width: 54px; height: 54px; border-radius: 50%; object-fit: cover; }
    .topic span { font-weight: 600; font-size: .92rem; }
    .car-btn {
      border: 0; width: 38px; height: 38px; border-radius: 999px; cursor: pointer;
      background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
      color: var(--primary-deep); font-size: 1.2rem;
    }

    .tools { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 14px; }
    .tool {
      background: var(--surface); border: 1px solid var(--border); border-radius: 14px;
      padding: 16px; box-shadow: 0 8px 20px rgba(22, 72, 77, .06);
    }
    .tool strong { display: block; margin-bottom: 6px; }
    .tool p { margin: 0; color: var(--muted); font-size: .92rem; }

    .reads-tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
    .reads-tabs button {
      border: 1px solid var(--border); background: var(--surface); color: var(--text);
      border-radius: 999px; padding: 8px 14px; font-weight: 600; cursor: pointer;
    }
    .reads-tabs button.active { background: var(--primary); color: white; border-color: transparent; }
    .reads-grid { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 14px; }
    .card { background: var(--surface); border: 1px solid var(--border); border-radius: 14px; overflow: hidden; box-shadow: 0 8px 20px rgba(16, 61, 66, .06); }
    .card img { width: 100%; height: 130px; object-fit: cover; display: block; }
    .card .content { padding: 12px; }
    .card h4 { margin: 4px 0 0; font-size: 1rem; line-height: 1.35; }

    .pillars { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 12px; }
    .pillar {
      background: linear-gradient(180deg, #ffffff, #f6fcfb);
      border: 1px solid var(--border); border-radius: 14px; padding: 16px;
    }
    .pillar h4 { margin: 0 0 6px; color: var(--primary-deep); }
    .pillar p { margin: 0; color: var(--muted); font-size: .92rem; }

    .newsletter {
      margin-top: 18px;
      background: linear-gradient(135deg, #0f6f6b 0%, #1e8f89 54%, #e98a73 100%);
      color: #f4fffc;
      border-radius: 20px; padding: 28px; display: grid; gap: 14px; align-items: center;
      grid-template-columns: 1.4fr 1fr;
    }
    .newsletter p { margin: 0; color: #ddf8f4; }
    .newsletter form { display: flex; gap: 8px; }
    .newsletter input {
      flex: 1; border: 0; border-radius: 12px; padding: 12px 14px; font: inherit;
    }
    .newsletter button {
      border: 0; border-radius: 12px; padding: 12px 16px; font-weight: 700;
      background: #f9bf58; color: #5f3a10; cursor: pointer;
    }
    #newsletter-msg { font-size: .9rem; min-height: 1.4em; }

    footer { padding: 32px 0 44px; color: var(--muted); font-size: .92rem; }

    @media (max-width: 1000px) {
      .hero { grid-template-columns: 1fr; }
      .reads-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .tools { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .pillars { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .newsletter { grid-template-columns: 1fr; }
    }
    @media (max-width: 640px) {
      .menu { overflow-x: auto; padding-bottom: 4px; }
      .reads-grid, .tools, .pillars { grid-template-columns: 1fr; }
      .mega { grid-template-columns: 1fr 1fr; }
      .hero-main img { height: 220px; }
    }
  </style>
</head>
<body>
