    <div class="ticker-track">
      <span class="ticker-item"><span class="ticker-dot"></span>Medically reviewed content</span>
      <span class="ticker-item"><span class="ticker-dot"></span>145 medical reviewers in network</span>
      <span class="ticker-item"><span class="ticker-dot"></span>21 years of experience</span>
      <span class="ticker-item"><span class="ticker-dot"></span>55 million monthly readers</span>
      <span class="ticker-item"><span class="ticker-dot"></span>Medically reviewed content</span>
      <span class="ticker-item"><span class="ticker-dot"></span>145 medical reviewers in network</span>
      <span class="ticker-item"><span class="ticker-dot"></span>21 years of experience</span>
      <span class="ticker-item"><span class="ticker-dot"></span>55 million monthly readers</span>
    </div>
  </div>

  <header>
    <div class="container nav">
      <a class="brand" href="index.html">Well<span>Source</span></a>
      <nav class="menu" aria-label="Main">
        <button data-menu="conditions">Health Conditions</button>
        <button data-menu="wellness">Wellness</button>
