      </div>
    </section>
  </main>

  <footer class="container">© 2026 WellSource Media. Informing healthier decisions every day.</footer>

  <script>
    const megaData = {
      conditions: {
        title: 'Health Conditions',
        cols: {
          'Common Conditions': ['Diabetes', 'Hypertension', 'Asthma', 'Arthritis'],
          'Chronic Care': ['Heart Disease', 'Migraines', 'Autoimmune', 'Sleep Disorders'],
          'Prevention': ['Screenings', 'Vaccines', 'Healthy Aging', 'Risk Factors']
        }
      },
      wellness: {
        title: 'Wellness',
        cols: {
          'Mind & Body': ['Stress Relief', 'Meditation', 'Movement', 'Sleep Hygiene'],
          'Nutrition': ['Healthy Eating', 'Supplements', 'Meal Planning', 'Hydration'],
          'Lifestyle': ['Work-Life Balance', 'Habits', 'Relationships', 'Productivity']
        }
      },
      tools: {
        title: 'Tools',
        cols: {
          'Calculators': ['BMI', 'Calories', 'Macros', 'Heart Risk'],
          'Finders': ['FindCare', 'Pharmacy Finder', 'Provider Search', 'Clinical Trials'],
          'Resources': ['Drug Directory', 'Pill Identifier', 'Symptom Checker', 'Lab Guide']
        }
      },
      featured: {
        title: 'Featured',
        cols: {
          'Editorial Picks': ['Top Stories', 'Editor’s Choice', 'Trending Topics', 'Ask an Expert'],
          'Series': ['Women’s Health', 'Men’s Health', 'Family Health', 'Seasonal Health'],
          'Special Reports': ['Allergy Outlook', 'Mental Health Month', 'Longevity', 'Sleep Week']
        }
      },
      connect: {
        title: 'Connect',
        cols: {
          'Community': ['Support Forums', 'Live Q&A', 'Patient Stories', 'Challenges'],
          'Newsletter': ['Daily Brief', 'Weekly Digest', 'Topic Alerts', 'Podcast'],
          'About': ['Our Standards', 'Medical Review Board', 'Editorial Team', 'Contact Us']
        }
      }
    };

    const menuButtons = document.querySelectorAll('.menu button');
    const mega = document.getElementById('mega-menu');

    function renderMega(key) {
      const data = megaData[key];
      mega.innerHTML = Object.entries(data.cols)
        .map(([heading, links]) => `<div><h4>${heading}</h4>${links.map(l => `<a href="#">${l}</a>`).join('')}</div>`)
        .join('');
    }

    menuButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        const isActive = btn.classList.contains('active');
        menuButtons.forEach(b => b.classList.remove('active'));
        if (isActive) {
          mega.classList.remove('open');
          return;
        }
        btn.classList.add('active');
        renderMega(btn.dataset.menu);
        mega.classList.add('open');
      });
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.nav')) {
        mega.classList.remove('open');
        menuButtons.forEach(b => b.classList.remove('active'));
      }
    });

    const readsData = {
      'Top Reads': [
        ['16 Superfoods That Are Worthy of the Title', 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?q=80&w=600&auto=format&fit=crop'],
        ['Does Ozempic Cause Hair Loss?', 'https://images.unsplash.com/photo-1631549916768-4119b4123a15?q=80&w=600&auto=format&fit=crop'],
        ['Can Music Therapy Help with Depression?', 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?q=80&w=600&auto=format&fit=crop'],
        ['These Are the 8 Best Calorie Counter Apps', 'https://images.unsplash.com/photo-1543165796-5426273eaab7?q=80&w=600&auto=format&fit=crop']
      ],
      'Fitness': [
        ['7 Mobility Moves You Can Do at Your Desk', 'https://images.unsplash.com/photo-1599058945522-28d584b6f0ff?q=80&w=600&auto=format&fit=crop'],
        ['How Often Should You Really Do Cardio?', 'https://images.unsplash.com/photo-1538805060514-97d9cc17730c?q=80&w=600&auto=format&fit=crop'],
        ['Strength Training Over 40: Starter Plan', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?q=80&w=600&auto=format&fit=crop'],
        ['Walking Workouts That Actually Challenge You', 'https://images.unsplash.com/photo-1476480862126-209bfaa8edc8?q=80&w=600&auto=format&fit=crop']
      ],
      'Mental Well-Being': [
        ['Micro-Habits That Lower Daily Stress', 'https://images.unsplash.com/photo-1499209974431-9dddcece7f88?q=80&w=600&auto=format&fit=crop'],
        ['A Therapist’s Guide to Better Boundaries', 'https://images.unsplash.com/photo-1516302752625-fcc3c50ae61f?q=80&w=600&auto=format&fit=crop'],
        ['How Sleep Debt Affects Your Mood', 'https://images.unsplash.com/photo-1455642305367-68834a7d3f89?q=80&w=600&auto=format&fit=crop'],
        ['Breathwork Basics for Beginners', 'https://images.unsplash.com/photo-1506126613408-eca07ce68773?q=80&w=600&auto=format&fit=crop']
      ],
      'Product Reviews': [
        ['Best Air Purifiers for Allergy Season', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?q=80&w=600&auto=format&fit=crop'],
        ['Do Smart Scales Help Long-Term?', 'https://images.unsplash.com/photo-1556228453-efd6c1ff04f6?q=80&w=600&auto=format&fit=crop'],
        ['Top Sleep Masks Tested by Editors', 'https://images.unsplash.com/photo-1515377905703-c4788e51af15?q=80&w=600&auto=format&fit=crop'],
        ['Our Favorite Blue-Light Glasses', 'https://images.unsplash.com/photo-1574258495973-f010dfbb5371?q=80&w=600&auto=format&fit=crop']
      ],
      'Recipes': [
        ['High-Protein Breakfasts in 15 Minutes', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?q=80&w=600&auto=format&fit=crop'],
        ['Low-Sodium Dinners That Still Taste Great', 'https://images.unsplash.com/photo-1543353071-087092ec393a?q=80&w=600&auto=format&fit=crop'],
        ['Sheet-Pan Meals for Busy Weeknights', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?q=80&w=600&auto=format&fit=crop'],
        ['Fiber-Rich Snacks for Better Gut Health', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?q=80&w=600&auto=format&fit=crop']
      ],
      'Skin Care': [
        ['Derm-Approved Morning Skincare Routine', 'https://images.unsplash.com/photo-1612817288484-6f916006741a?q=80&w=600&auto=format&fit=crop'],
        ['What to Know About Retinol Strengths', 'https://images.unsplash.com/photo-1596755389378-c31d21fd1273?q=80&w=600&auto=format&fit=crop'],
        ['How to Support Skin Barrier Health', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?q=80&w=600&auto=format&fit=crop'],
        ['SPF Myths, Debunked by Dermatologists', 'https://images.unsplash.com/photo-1590439471364-192aa70c0b53?q=80&w=600&auto=format&fit=crop']
      ]
    };

    const tabsWrap = document.getElementById('reads-tabs');
    const grid = document.getElementById('reads-grid');

    function renderCards(tabName) {
      grid.innerHTML = readsData[tabName].map(([title, image]) => `
        <article class="card">
          <img src="${image}" alt="${title}">
          <div class="content"><div class="tag">${tabName}</div><h4>${title}</h4></div>
        </article>`).join('');
    }

    Object.keys(readsData).forEach((name, index) => {
      const btn = document.createElement('button');
      btn.textContent = name;
      if (index === 0) btn.classList.add('active');
      btn.addEventListener('click', () => {
        [...tabsWrap.children].forEach(c => c.classList.remove('active'));
        btn.classList.add('active');
        renderCards(name);
      });
      tabsWrap.appendChild(btn);
    });
    renderCards('Top Reads');

    const carousel = document.getElementById('topics-carousel');
    document.getElementById('topic-left').addEventListener('click', () => carousel.scrollBy({left: -250, behavior: 'smooth'}));
