        [...tabsWrap.children].forEach(c => c.classList.remove('active'));
        btn.classList.add('active');
        renderCards(name);
      });
      tabsWrap.appendChild(btn);
    });
    renderCards('Top Reads');

    const carousel = document.getElementById('topics-carousel');
    document.getElementById('topic-left').addEventListener('click', () => carousel.scrollBy({left: -250, behavior: 'smooth'}));
    document.getElementById('topic-right').addEventListener('click', () => carousel.scrollBy({left: 250, behavior: 'smooth'}));

    const form = document.getElementById('newsletter-form');
    const msg = document.getElementById('newsletter-msg');
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('email').value.trim();
      if (!email) return;
      msg.textContent = `Thanks! ${email} is subscribed to the WellSource newsletter.`;
      form.reset();
    });
  </script>
